  async setAsOf(date: string): Promise<void> {
    const id = this.sheet();
    if (!id) throw new Error('No sheet is loaded.');
    const was = this.asOf();
    this.asOf.set(date);
    try {
      await this.loadSheet(id);
    } catch (e) {
